// ===== Collect jobs: job-alert emails + remote job boards + company career pages =====
// Edit the lists below to change companies / sources.
const ATS = [
  // [system, slug, company name, product/service]
  ['lever', 'zeta', 'Zeta', 'Product'], ['greenhouse', 'devrev', 'DevRev', 'Product'],
  ['lever', 'cred', 'CRED', 'Product'], ['greenhouse', 'groww', 'Groww', 'Product'],
  ['lever', 'meesho', 'Meesho', 'Product'], ['lever', 'hevodata', 'Hevo Data', 'Product'],
  ['ashby', 'sarvam', 'Sarvam AI', 'Product'],
  ['greenhouse', 'stripe', 'Stripe', 'Product'], ['greenhouse', 'databricks', 'Databricks', 'Product'],
  ['greenhouse', 'gitlab', 'GitLab', 'Product'], ['greenhouse', 'cloudflare', 'Cloudflare', 'Product'],
  ['greenhouse', 'okta', 'Okta', 'Product'], ['greenhouse', 'intercom', 'Intercom', 'Product'],
  ['greenhouse', 'wise', 'Wise', 'Product'], ['greenhouse', 'n26', 'N26', 'Product'],
  ['greenhouse', 'adyen', 'Adyen', 'Product'], ['greenhouse', 'gocardless', 'GoCardless', 'Product'],
  ['greenhouse', 'agoda', 'Agoda', 'Product'], ['greenhouse', 'vercel', 'Vercel', 'Product'],
  ['ashby', 'n8n', 'n8n', 'Product'], ['ashby', 'miro', 'Miro', 'Product'],
  ['ashby', 'supabase', 'Supabase', 'Product'], ['ashby', 'posthog', 'PostHog', 'Product'],
  ['ashby', 'linear', 'Linear', 'Product'], ['ashby', 'replit', 'Replit', 'Product'],
  ['ashby', 'perplexity', 'Perplexity', 'Product'], ['ashby', 'cohere', 'Cohere', 'Product'],
  ['ashby', 'zapier', 'Zapier', 'Product'],
];
const ROLE = /(front[\s-]?end|frontend|react|full[\s-]?stack|fullstack|mern|node\.?js|javascript|typescript|next\.?js|\bui\b|\bai\b|artificial intelligence|machine learning|\bml\b|llm|gen ?ai|generative|agentic|software (engineer|developer)|\bsde\b|product engineer|application developer|java\b)/i;

const H = { 'User-Agent': 'Mozilla/5.0 (personal job alert bot)' };
const get = (url, json = true) => this.helpers.httpRequest({ url, json, timeout: 20000, headers: H }).catch(() => null);
const decode = s => String(s || '').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;|&rsquo;|&#x27;/g, "'").replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
const strip = s => decode(decode(s)).replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
const hash = s => { let h = 5381; for (const c of String(s)) h = ((h * 33) ^ c.charCodeAt(0)) >>> 0; return h.toString(36); };
const jobs = [];
const stats = {};
const add = (j) => {
  if (!j.link || !j.role) return;
  stats[j.source] = (stats[j.source] || 0) + 1;
  jobs.push({ company: '', location: '', workMode: '', salary: '', companyType: '', posted: '', ...j, description: strip(j.description).slice(0, 1800) });
};

// ---------- 1. Job alert emails (Gmail node output) ----------
for (const item of $input.all()) {
  const m = item.json || {};
  const html = m.html || m.textAsHtml || '';
  if (!html) continue;
  const from = JSON.stringify(m.from || '').toLowerCase();
  const src = from.includes('linkedin') ? 'LinkedIn alert' : from.includes('naukri') ? 'Naukri alert' : from.includes('instahyre') ? 'Instahyre alert' : from.includes('cutshort') ? 'Cutshort alert' : from.includes('wellfound') ? 'Wellfound alert' : 'Email alert';
  const map = {};
  const re = /<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
  let a;
  while ((a = re.exec(html))) {
    const href = decode(a[1]);
    let id, link, mm;
    if ((mm = href.match(/linkedin\.com\/(?:comm\/)?jobs\/view\/(\d+)/))) { id = 'li-' + mm[1]; link = 'https://www.linkedin.com/jobs/view/' + mm[1] + '/'; }
    else if ((mm = href.match(/naukri\.com\/(?:jd\/)?(job-listings-[a-z0-9-]+?-(\d{9,14}))(?=[?#]|$)/i))) { id = 'nk-' + mm[2]; link = 'https://www.naukri.com/' + mm[1]; }
    else if ((mm = href.match(/instahyre\.com\/job-(\d+)[^?#]*/))) { id = 'ih-' + mm[1]; link = 'https://www.' + mm[0].replace(/^.*?instahyre/, 'instahyre'); }
    else if ((mm = href.match(/cutshort\.io\/job\/[^?#]+/))) { link = 'https://' + mm[0]; id = 'cs-' + hash(mm[0]); }
    else if ((mm = href.match(/wellfound\.com\/jobs\/(\d+[^?#]*)/))) { link = 'https://wellfound.com/jobs/' + mm[1]; id = 'wf-' + mm[1].split('-')[0]; }
    else continue;
    const t = strip(a[2]);
    map[id] = map[id] || { id, link, texts: [] };
    if (t && !map[id].texts.includes(t)) map[id].texts.push(t);
  }
  for (const v of Object.values(map)) {
    let ctx = v.texts.join(' | ');
    let exp = '';
    const nm = v.link.match(/job-listings-(.+)-(\d+)-to-(\d+)-years-\d+$/);
    if (nm) { ctx = nm[1].replace(/-/g, ' ') + ' | ' + ctx; exp = nm[2] + '-' + nm[3] + ' yrs'; }
    if (!ctx.trim()) continue;
    add({ jobId: v.id, source: src, role: ctx.slice(0, 160), fromEmail: true, experience: exp, description: 'Job alert email text: ' + ctx + (exp ? ' | Experience: ' + exp : ''), link: v.link, posted: m.date || '' });
  }
}

// ---------- 2. Remote job boards ----------
const [rem, rok, him, wwr1, wwr2] = await Promise.all([
  get('https://remotive.com/api/remote-jobs?category=software-dev&limit=150'),
  get('https://remoteok.com/api'),
  get('https://himalayas.app/jobs/api?limit=100'),
  get('https://weworkremotely.com/categories/remote-full-stack-programming-jobs.rss', false),
  get('https://weworkremotely.com/categories/remote-front-end-programming-jobs.rss', false),
]);
for (const j of (rem && rem.jobs) || []) add({ jobId: 'rm-' + j.id, source: 'Remotive', role: j.title, company: j.company_name, location: j.candidate_required_location || 'Remote', workMode: 'Remote', salary: j.salary || '', description: (j.tags || []).join(', ') + ' ' + j.description, link: j.url, posted: j.publication_date });
for (const j of (Array.isArray(rok) ? rok : []).filter(x => x.id && x.position)) add({ jobId: 'ro-' + j.id, source: 'RemoteOK', role: j.position, company: j.company, location: j.location || 'Remote', workMode: 'Remote', salary: j.salary_min ? `USD ${j.salary_min}-${j.salary_max} per year` : '', description: (j.tags || []).join(', ') + ' ' + j.description, link: j.url, posted: j.date });
for (const j of (him && him.jobs) || []) {
  let pd = j.pubDate; if (typeof pd === 'number') pd = new Date(pd < 1e12 ? pd * 1000 : pd).toISOString();
  add({ jobId: 'hm-' + hash(j.guid || j.applicationLink), source: 'Himalayas', role: j.title, company: j.companyName, location: (j.locationRestrictions || []).join(', ') || 'Worldwide', workMode: 'Remote', salary: j.minSalary ? `${j.currency || ''} ${j.minSalary}-${j.maxSalary || ''} ${j.salaryPeriod || ''}` : '', description: (j.excerpt || '') + ' ' + (j.description || ''), link: j.applicationLink || j.guid, posted: pd || '' });
}
for (const x of [wwr1, wwr2]) {
  for (const it of String(x || '').split('<item>').slice(1)) {
    const tag = n => { const mm = it.match(new RegExp('<' + n + '>(?:<!\\[CDATA\\[)?([\\s\\S]*?)(?:\\]\\]>)?</' + n + '>')); return mm ? mm[1].trim() : ''; };
    const title = decode(tag('title')); const parts = title.split(':');
    const company = parts.length > 1 ? parts.shift().trim() : '';
    add({ jobId: 'ww-' + hash(tag('link')), source: 'WeWorkRemotely', role: parts.join(':').trim(), company, location: tag('region') || 'Remote', workMode: 'Remote', description: tag('description'), link: tag('link'), posted: tag('pubDate') });
  }
}

// ---------- 3. Company career pages (Greenhouse / Lever / Ashby public job APIs) ----------
await Promise.all(ATS.map(async ([sys, slug, name, type]) => {
  if (sys === 'greenhouse') {
    const d = await get(`https://boards-api.greenhouse.io/v1/boards/${slug}/jobs`);
    const list = ((d && d.jobs) || []).filter(j => ROLE.test(j.title)).slice(0, 25);
    await Promise.all(list.map(async j => {
      const det = await get(`https://boards-api.greenhouse.io/v1/boards/${slug}/jobs/${j.id}`);
      add({ jobId: 'gh-' + j.id, source: 'Careers: ' + name, role: j.title, company: name, companyType: type, location: (j.location && j.location.name) || '', description: det ? det.content : '', link: j.absolute_url, posted: j.updated_at });
    }));
  } else if (sys === 'lever') {
    const d = await get(`https://api.lever.co/v0/postings/${slug}?mode=json&limit=300`);
    for (const j of (Array.isArray(d) ? d : []).filter(j => ROLE.test(j.text)).slice(0, 25)) {
      const sr = j.salaryRange ? `${j.salaryRange.currency} ${j.salaryRange.min}-${j.salaryRange.max} ${j.salaryRange.interval || ''}` : '';
      add({ jobId: 'lv-' + j.id, source: 'Careers: ' + name, role: j.text, company: name, companyType: type, location: ((j.categories && (j.categories.allLocations || [j.categories.location])) || []).join(', '), workMode: j.workplaceType || '', salary: sr, description: j.descriptionPlain || j.description, link: j.hostedUrl, posted: j.createdAt ? new Date(j.createdAt).toISOString() : '' });
    }
  } else if (sys === 'ashby') {
    const d = await get(`https://api.ashbyhq.com/posting-api/job-board/${slug}?includeCompensation=true`);
    for (const j of ((d && d.jobs) || []).filter(j => ROLE.test(j.title)).slice(0, 25)) {
      const locs = [j.location].concat((j.secondaryLocations || []).map(s => s.location)).filter(Boolean).join(', ');
      add({ jobId: 'ab-' + j.id, source: 'Careers: ' + name, role: j.title, company: name, companyType: type, location: locs, workMode: j.isRemote ? 'Remote' : (j.workplaceType || ''), salary: (j.compensation && j.compensation.compensationTierSummary) || '', description: j.descriptionPlain || j.descriptionHtml, link: j.jobUrl, posted: j.publishedAt });
    }
  }
}));

// de-duplicate inside this run
const seen = new Set();
const out = jobs.filter(j => !seen.has(j.jobId) && seen.add(j.jobId));
if (!out.length) return [];
return out.map(j => ({ json: { ...j, _stats: stats } }));

// ===== Rule filter + build the Gemini prompt =====
// Your rules - edit here. Salary values are examples (LPA = lakh INR per year).
const RULES = {
  chennaiProductMinLPA: 12,
  chennaiServiceMinLPA: 14,
  outsideChennaiMinLPA: 20,
  preferredCountries: ['United States', 'United Kingdom', 'Germany', 'Singapore', 'Ireland', 'Canada', 'Australia', 'New Zealand', 'UAE (Dubai)'], // edit to your preferred countries
  maxJobsToScore: 40,
  maxPostAgeDays: 7,
};
const TARGETS = /(freshworks|zoho|chargebee|kissflow|uniphore|facilio|surveysparrow|hippo ?video|gofrugal|vue\.?ai|mad street den|detect technologies|saama|pickyourtrail|paypal|standard chartered|barclays|bank of america|citi|mr\.? cooper|temenos|amazon|walmart|comcast|ford|caterpillar|hmh|houghton|pearson|ideas2it|tiger analytics|payoda|indium|zeta|devrev|cred|groww|meesho|hevo|sarvam)/i;
const ROLE = /(front[\s-]?end|frontend|react|full[\s-]?stack|fullstack|mern|node\.?js|javascript|typescript|next\.?js|\bui\b|\bai\b|artificial intelligence|machine learning|\bml\b|llm|gen ?ai|generative|agentic|software (engineer|developer)|\bsde\b|product engineer|application developer|java\b)/i;
const EXCLUDE = /(principal|\bstaff\b|director|head of|\bvp\b|vice president|manager|\bintern\b|internship|trainee|fresher|android|\bios\b|embedded|sales|marketing|recruit|account exec|designer|\bqa\b|test engineer|sdet|devops|\bsre\b|site reliability|data engineer|\.net\b|php|golang|\bgo engineer|rust\b|salesforce|\bsap\b|mainframe|support engineer|security engineer|hardware|firmware|mechanical|electrical|scientist|researcher|research engineer)/i;
const INDIA = /(india|chennai|bengaluru|bangalore|hyderabad|pune|mumbai|delhi|gurgaon|gurugram|noida|kochi|coimbatore|kolkata|ahmedabad|trivandrum|thiruvananthapuram|mysore|remote - in|\bin\b$)/i;
const OPEN_REMOTE = /(worldwide|anywhere|global|apac|asia|india|^remote$|^$)/i;
const VISA_YES = /(visa sponsorship|sponsor(ship)? (your |a |the )?visa|visa support|relocation (support|assistance|package|bonus)|we (will|can) sponsor|sponsorship (is )?available)/i;
const VISA_NO = /(no visa sponsorship|not (be )?(able to )?sponsor|unable to sponsor|cannot sponsor|can't sponsor|does not sponsor|without (the need for )?sponsorship|must (already )?have (the )?(right|authori[sz]ation) to work)/i;

const lpaFrom = (s) => {
  s = String(s || '');
  let m = s.match(/(\d+(?:\.\d+)?)\s*(?:-|to)\s*(\d+(?:\.\d+)?)\s*(lacs|lakhs?|lpa|l\b)/i);
  if (m) return parseFloat(m[2]);
  m = s.match(/(?:usd|\$)\s*([\d,]+)\s*(?:-|to)\s*\$?([\d,]+)/i);
  if (m) { const v = parseFloat(m[2].replace(/,/g, '')); if (v > 10000) return v * 88 / 1e5; }
  return null; // unknown
};

const now = Date.now();
const kept = [];
const dropped = {};
const drop = (why) => { dropped[why] = (dropped[why] || 0) + 1; };
for (const { json: j } of $input.all()) {
  const title = j.role || '';
  if (!ROLE.test(title)) { drop('role'); continue; }
  if (EXCLUDE.test(j.fromEmail ? title.split('|')[0] : title)) { drop('excluded title'); continue; }
  if (j.posted && !j.fromEmail) {
    const t = Date.parse(j.posted);
    const maxAge = String(j.source).startsWith('Careers') ? 60 : RULES.maxPostAgeDays;
    if (t && now - t > maxAge * 864e5) { drop('old'); continue; }
  }
  const expMin = (j.experience || '').match(/^(\d+)/);
  if (expMin && +expMin[1] >= 7) { drop('experience 7+'); continue; }

  const loc = (j.location || '').trim();
  const text = loc + ' ' + j.description;
  const chennai = /chennai/i.test(loc + ' ' + (j.fromEmail ? title : ''));
  const india = j.fromEmail || INDIA.test(loc);
  let zone;
  if (chennai) zone = 'Chennai';
  else if (india) zone = 'India (outside Chennai)';
  else if ((j.workMode || '').toLowerCase().includes('remote') && OPEN_REMOTE.test(loc.replace(/remote[,\s-]*/i, '').trim())) zone = 'Remote (open to India)';
  else {
    zone = 'Overseas';
    if (!VISA_YES.test(text) || VISA_NO.test(text)) { drop('overseas without visa sponsorship'); continue; }
  }
  const lpa = lpaFrom(j.salary + ' ' + (j.fromEmail ? j.description : ''));
  const min = zone === 'Chennai' ? RULES.chennaiProductMinLPA : RULES.outsideChennaiMinLPA;
  if (lpa !== null && lpa < min) { drop('salary below minimum'); continue; }

  let priority = 0;
  if (TARGETS.test(j.company + ' ' + title)) priority += 3;
  if (zone === 'Chennai') priority += 2;
  if (j.fromEmail) priority += 1;
  if (/react|full[\s-]?stack|ai engineer|ai developer|llm|gen ?ai/i.test(title)) priority += 1;
  kept.push({ ...j, zone, salaryLPA: lpa, priority });
}
kept.sort((a, b) => b.priority - a.priority);
const jobs = kept.slice(0, RULES.maxJobsToScore);
if (!jobs.length) return [];

const profile = `CANDIDATE: <Your name>, <City>, <Country>. <Current title>, <N> years experience.
Skills: <your main skills>.
AI: <AI tools and frameworks you use>.
Work: <one line per recent project or role>.
Education: <degree>.
TARGET ROLES: Frontend Developer; Full Stack (React + Node, Java OK); AI Developer / AI Engineer.
SALARY RULES: home-city product company >= ${RULES.chennaiProductMinLPA} LPA; home-city service company >= ${RULES.chennaiServiceMinLPA} LPA; anywhere else >= ${RULES.outsideChennaiMinLPA} LPA (or equivalent).
OVERSEAS: must offer visa sponsorship; preferred countries: ${RULES.preferredCountries.join(', ')}.
PREFERENCES: product companies preferred over IT services/consulting.`;

const list = jobs.map((j, i) => `### JOB ${i + 1}\nid: ${j.jobId}\nsource: ${j.source}\ntitle: ${j.role}\ncompany: ${j.company || '(see text)'}\nlocation: ${j.location || '(see text)'} | zone: ${j.zone} | mode: ${j.workMode || '?'}\nsalary: ${j.salary || 'not stated'}\ntext: ${j.description.slice(0, 900)}`).join('\n\n');

const prompt = `You are a strict career assistant screening jobs for one candidate.\n\n${profile}\n\nScore each job 0-100 for how good an application would be: role match to target roles and skills (50%), seniority fit for 4-5 years experience (15%), company quality and product-company preference (15%), likelihood the pay meets the salary rules (20%). Give a score below 60 if the job clearly breaks a rule (wrong role family, needs 7+ years, IT-services company in Chennai unlikely to pay 15 LPA, outside Chennai and unlikely to pay 24 LPA, overseas without sponsorship). Some jobs come from email alerts where title, company and location are mixed into one text line - work out the real values.\n\nReturn ONLY a JSON array, no markdown, one object per job, in this exact shape:\n[{"id":"...","score":0,"role":"clean job title","company":"company name","location":"city, country","workMode":"Onsite|Hybrid|Remote","companyType":"Product|Service|Unknown","salary":"stated or estimated range in LPA or currency","why":"max 25 words why it fits","gaps":"max 15 words main gap or risk"}]\n\nJOBS:\n\n${list}`;

return [{ json: { prompt, jobs, keptCount: kept.length, dropped, stats: ($input.first().json._stats) || {} } }];

// ===== Read Gemini scores, keep the best jobs, build tracker row + Telegram message =====
const MIN_SCORE = 70;      // only send jobs scoring at least this
const MAX_PER_RUN = 5;     // 2 runs a day -> up to 10 jobs a day
const N8N_URL = 'http://localhost:5678';

const raw = String($input.first().json.text || $input.first().json.output || "").replace(/`{3}json|`{3}/g, '').trim();
let scores = [];
try { scores = JSON.parse(raw.slice(raw.indexOf('['), raw.lastIndexOf(']') + 1)); } catch (e) { throw new Error('Could not read Gemini JSON: ' + raw.slice(0, 300)); }
const jobs = $('Filter & build prompt').first().json.jobs;
const byId = Object.fromEntries(jobs.map(j => [j.jobId, j]));
const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const today = $now.setZone('Asia/Kolkata').toFormat('yyyy-MM-dd');

const best = scores
  .filter(s => byId[s.id] && Number(s.score) >= MIN_SCORE)
  .sort((a, b) => b.score - a.score)
  .slice(0, MAX_PER_RUN);

return best.map(s => {
  const j = byId[s.id];
  const company = s.company || j.company;
  const role = s.role || j.role;
  const type = j.companyType || s.companyType || 'Unknown';
  const base = `${N8N_URL}/webhook/job-decision?id=${encodeURIComponent(j.jobId)}`;
  const text =
`<b>🎯 ${s.score}/100 · ${esc(role)}</b>
🏢 ${esc(company)} (${esc(type)})
📍 ${esc(s.location || j.location || j.zone)} · ${esc(s.workMode || j.workMode || '?')}
💰 ${esc(s.salary || j.salary || 'not stated')}
✅ ${esc(s.why)}
⚠️ ${esc(s.gaps)}
📨 ${esc(j.source)}

<a href="${base}&d=apply&u=${encodeURIComponent(j.link)}">✅ Apply (opens job + marks Applied)</a>
<a href="${base}&d=skip">❌ Skip</a>`;
  return {
    json: {
      row: {
        'Job ID': j.jobId, 'Date Found': today, 'Source': j.source, 'Company': company, 'Role': role,
        'Location': s.location || j.location || j.zone, 'Work Mode': s.workMode || j.workMode || '',
        'Salary': s.salary || j.salary || '', 'Company Type': type, 'Fit Score': s.score,
        'Why It Fits': s.why || '', 'Gaps': s.gaps || '', 'Link': j.link, 'Status': 'Pending',
        'Applied On': '', 'Follow-up On': '', 'Notes': '',
      },
      tgText: text,
      link: j.link,
    },
  };
});
